urlset:
{#- Same as Zola's built-in sitemap, except that posts with `extra.hidden = true` are left out. #}
{%- for sitemap_entry in entries %}
{%- if not sitemap_entry.extra.hidden %}

    {{ sitemap_entry.permalink | escape_xml | safe }}
    {%- if sitemap_entry.updated %}
    {{ sitemap_entry.updated }}
    {%- endif %}

{%- endif %}
{%- endfor %}
